/* ===== 全局优化整合 ===== */
:root {
  /* 1. 顶栏底栏半透明 */
  --chat-header-bg: rgba(250, 250, 250, 0.45) !important;
  --input-area-bg: rgba(250, 250, 250, 0.65) !important;

