  /* 4. 旁白字体调整 */
  --narration-font-size: 0.7em !important;
  --narration-color: rgba(66, 66, 66, 0.9) !important;
  --narration-font-family: sans-serif !important;

  /* 5. 气泡样式优化 */
  --bubble-them-radius: 12px 12px 12px 4px !important;
