  --bubble-them-padding: 8px 10px !important;
  --bubble-them-bg: rgba(250, 250, 250, 0.65) !important;
  --bubble-them-color: #666 !important;
  --bubble-them-border: 1px solid rgba(255, 255, 255, 0.8) !important;
  --bubble-them-shadow: 0 0 15px rgba(255, 255, 255, 0.5) !important;

  --bubble-me-radius: 12px 12px 4px 12px !important;
  --bubble-me-align: flex-end !important;
  --bubble-me-margin: 0.5rem 1rem 0.5rem 0.5rem !important;
  --bubble-me-padding: 8px 10px !important;
  --bubble-me-bg: rgba(200, 235, 250, 0.65) !important;
  --bubble-me-color: #666 !important;
  --bubble-me-border: 1px solid rgba(255, 255, 255, 0.8) !important;
  --bubble-me-shadow: 0 0 15px rgba(255, 255, 255, 0.5) !important;
  --bubble-max-width: 70% !important;

  /* 6. 输入框样式 */
  --input-box-border: 1px solid #88C6ED !important; /* 改为灰色边框 */
