}

/* ========== 自定义占位符 ========== */
.input-box-custom::placeholder,
.input-box-custom::-webkit-input-placeholder {
  color: transparent !important;
  opacity: 0 !important;
}

.input-action-bar-custom {
  position: relative !important;
  padding-top: 2px !important;
  padding-bottom: 2px !important;
  min-height: 36px !important;
}

.input-action-bar-custom::before {
  content: &quot;❄️˚‧이번 겨울에 눈송이는 달달해요? .♡͙·&quot;;
  position: absolute;
  left: 18px !important;
  top: 50% !important;
  transform: translateY(-50%) !important;
  z-index: 9 !important;
  font-size: 13px !important;
