}

.header-action-btn {
  opacity: 0 !important;
  pointer-events: auto !important;
}

.header-action-btn.info-btn {
  opacity: 1 !important;
}

.header-btn-back {
  opacity: 1 !important;
}

.header-btn-back,
.header-action-btn.info-btn {
  opacity: 1 !important;
  color: #88C6ED !important; /* 改为灰色 */
}

.glass-header {
  display: flex !important;
  justify-content: space-between !important;
  align-items: center !important;
  padding: 0 16px !important;
  height: 60px !important;
}

/* ===== 按钮透明化 ===== */
.input-btns-right &gt; *:not(.input-btn-plus) {
  background: transparent !important;
  color: transparent !important;
  opacity: 0 !important;
}

.input-btns-right &gt; *:not(.input-btn-plus) svg,
.input-btns-right &gt; *:not(.input-btn-plus) path {
  opacity: 0 !important;
